				PEEK_DISCARD(address_len);
				addresses_len -= address_len;
				address_len = PEEK_UINT16;
				addresses_len -= 2;
				if (addresses_len < address_len) {
					log_warn("cdp",
					    "too short address subframe "
					    "received on %s",
					    hardware->h_ifname);
					goto malformed;
				}
				PEEK_DISCARD(address_len);
				addresses_len -= address_len;
				(void)PEEK_SAVE(pos_next_address);
				/* Next, we go back and try to extract
