					mgmt = lldpd_alloc_mgmt(LLDPD_AF_IPV4, &addr,
					    sizeof(struct in_addr), 0);
					if (mgmt == NULL) {
						if (errno == ENOMEM)
							log_warn("cdp",
							    "unable to allocate memory for management address");
						else
							log_warn("cdp",
							    "too large management address received on %s",
							    hardware->h_ifname);
						goto malformed;
					}
					TAILQ_INSERT_TAIL(&chassis->c_mgmt, mgmt,
					    m_entries);
				}
